window.AUTH=window.AUTH||{};window.AUTH["24-345"]={"d":"24-345","id":"2025/24-345","n":"FS Credit Opportunities Corp. v. Saba Capital Master Fund, Ltd.","briefs":[{"k":"petitioner","label":"Brief of petitioners, and the BlackRock respondents supporting petitioners,","date":"2025-08-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-345/370968/20250827174947861_FS%20Credit%20Opportunities%20Corp.%20v.%20Saba%20-%20Opening%20Brief%20FILE.pdf","side":"pet","n":108},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-09-03","url":"https://www.supremecourt.gov/DocketPDF/24/24-345/373568/20250903162813269_24-345_FSCredit_Merits_Amicus.pdf","side":"us","n":73},{"k":"respondent","label":"Brief of respondents Saba Capital Master Fund, Ltd., et al.","date":"2025-10-09","url":"https://www.supremecourt.gov/DocketPDF/24/24-345/379284/20251009145913210_24-345%20Brief%20for%20Respondents.pdf","side":"res","n":44},{"k":"reply","label":"Reply Brief of petitioners, and the BlackRock respondents supporting petitioners,","date":"2025-11-10","url":"https://www.supremecourt.gov/DocketPDF/24/24-345/384093/20251110160501914_FS%20Credit%20Opportunities%20Corp.%20v.%20Saba%20-%20Merits%20Reply%20Brief%20FILE.pdf","side":"pet","n":65}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us2r47_m64o.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":12,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"1, 15, 20, 21, 23","1":"2, 3, 12, 14, 21, 23, 29","2":"13, 23, 24, 27, 32, 36, 42, 48","3":"5, 6, 7, 16, 17"}},{"t":"case","label":"Astra USA, Inc. v. Santa Clara County","cite":"563 U.S. 110","y":2011,"id":"2010/09-1273","sc":1,"sum":"The Court held that health care providers cannot sue drug makers for overcharging public hospitals for prescription drugs.","sumSrc":"Oyez","by":{"0":"24, 25","2":"36","3":"5"}},{"t":"case","label":"Batka v. Liberty Mutual Fire Insurance Co.","cite":"704 F.2d 684","y":1983,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/704/684/","by":{"0":"43"}},{"t":"case","label":"Beck Chevrolet Co. v. General Motors LLC","cite":"787 F.3d 663","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/787/663/","by":{"0":"18"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"ar":2,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 29"}},{"t":"case","label":"Board of Governors of Federal Reserve System v. Investment Company Institute","cite":"450 U.S. 46","y":1981,"id":"1980/79-927","sc":1,"sum":"The amendment to Regulation Y does not exceed the Board's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 9","2":"16"}},{"t":"case","label":"Botany Worsted Mills v. United States","cite":"278 U.S. 282","y":1929,"id":"scdb/1928-021","sc":1,"sum":"(1) That the informal settlement did not constitute a binding agreement. P. 289. (2) That the taxpayer was not estopped by the settlement from recovering any portion of the tax to which it might otherwise have been entitled. Id.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"op":3,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 33","1":"24","2":"2, 10, 48, 49","3":"7, 14"}},{"t":"case","label":"CC Disposal, Inc. v. Veolia ES Valley View Landfill, Inc.","cite":"406 Ill. App. 3d 783","y":2010,"url":"https://www.courtlistener.com/c/Ill.%20App.%203d/406/783/","by":{"0":"32"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"op":2,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"27, 29","2":"37"}},{"t":"case","label":"Chase Manhattan Bank, N.A. New York v. Clusiau Sales & Rental, Inc.","cite":"308 N.W.2d 490","y":1981,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/308/490/","by":{"0":"43"}},{"t":"case","label":"Cort v. Ash","cite":"422 U.S. 66","y":1975,"id":"1974/73-1908","sc":1,"op":1,"ar":2,"sum":"Respondent stockholder brought this action seeking damages in favor of petitioner Bethlehem Steel Corp., a Delaware corporation, and injunctive relief because of advertisements in connection with the 1972 Presidential election that petitioner corporate directors had authorized from general corporate funds in alleged violation of 18 U. S. C. § 610, which prohibits corporations from making contributions or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27, 28","2":"10"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"20, 21"}},{"t":"case","label":"Daily Income Fund, Inc. v. Fox","cite":"464 U.S. 523","y":1984,"id":"1983/82-1200","sc":1,"op":1,"sum":"Rule 23.1 does not apply to an action brought by an investment company shareholder under § 36(b), and thus the plaintiff in such a case need not first make a demand upon the company's directors before bringing suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 25","1":"5","2":"5, 27, 36"}},{"t":"case","label":"Duarte v. Pacific Specialty Insurance Co.","cite":"13 Cal. App. 5th 45","y":2017,"url":"https://www.courtlistener.com/c/Cal.%20App.%205th/13/45/","by":{"0":"43"}},{"t":"case","label":"E. I. du Pont de Nemours & Co. v. Collins","cite":"432 U.S. 46","y":1977,"id":"1976/75-1870","sc":1,"sum":"In approving the merger of a closed-end investment company (Christiana), 98% of whose assets consisted of Du Pont & Co. common stock, into an affiliate company (Du Pont), the Securities and Exchange Commission (SEC) held to have reasonably exercised its discretion under § 17(b) of the Investment Company Act of 1940, as amended, in valuing Christiana essentially on the basis of the market value of Du Pont stock …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","1":"23"}},{"t":"case","label":"Eaton Vance Senior Income Trust v. Saba Capital Master Fund, Ltd.","cite":"2024 WL 4579652","y":2024,"court":"Mass. Super. Ct. Oct. 21","by":{"0":"12"}},{"t":"case","label":"Gollust v. Mendell","cite":"501 U.S. 115","y":1991,"id":"1990/90-659","sc":1,"sum":"Mendell has satisfied the statute's standing requirements.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Gonzaga University v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"op":2,"ar":9,"sum":"Reasoning that because the Secretary of Education is authorized to enforce the Family Educational Rights and Privacy Act of 1974, it does not create privately enforceable rights.","sumSrc":"opinion","by":{"0":"22, 24","1":"3, 4, 15, 20, 21","2":"26, 27, 32, 36"}},{"t":"case","label":"Green v. Nuveen Advisory Corp.","cite":"295 F.3d 738","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/295/738/","by":{"0":"12"}},{"t":"case","label":"Guardians Ass’n v. Civil Service Commission of City of New York","cite":"463 U.S. 582","y":1983,"id":"1982/81-431","sc":1,"op":1,"sum":"The judgment is affirmed. 633 F. 2d 232, affirmed. JUSTICE WHITE concluded that discriminatory intent is not an essential element of a Title VI violation. JUSTICE WHITE, joined by JUSTICE REHNQUIST, also concluded that a private plaintiff should recover only injunctive, noncompensatory relief for a defendant's unintentional violation of Title VI, that such relief should not include an award of constructive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"589 U.S. 221","y":2020,"id":"2019/18-776","sc":1,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Hernandez v. Mesa","cite":"589 U.S. 93","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"0":"27, 28","1":"5, 13"}},{"t":"case","label":"I. Meyer Pincus & Associates, P.C. v. Oppenheimer & Co.","cite":"936 F.2d 759","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/936/759/","by":{"0":"9, 10"}},{"t":"case","label":"J. I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"op":2,"ar":1,"sum":"Respondent, stockholder of petitioner company, brought a civil action in federal court for deprivation of his and other stockholders' preemptive rights by reason of a merger involving the company, allegedly effected through use of a false and misleading proxy statement. The complaint has two counts, one based on diversity and claiming a breach of directors' fiduciary duty to stockholders and the other alleging a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 26, 27, 28","2":"10","3":"4"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"584 U.S. 241","y":2018,"id":"2017/16-499","sc":1,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"0":"20, 27"}},{"t":"case","label":"Johnson v. Interstate Management Co.","cite":"849 F.3d 1093","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/849/1093/","by":{"0":"26"}},{"t":"case","label":"Karahalios v. National Federation of Federal Employees","cite":"489 U.S. 527","y":1989,"id":"1988/87-636","sc":1,"op":1,"sum":"Title VII of the CSRA does not confer on federal employees a private cause of action against a breach by a union representing such employees of its statutory duty of fair representation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24","2":"36","3":"17"}},{"t":"case","label":"Kardon v. National Gypsum Co.","cite":"69 F. Supp. 512","y":1946,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./69/512/","ar":1,"by":{"0":"28"}},{"t":"case","label":"Keyes v. Brown","cite":"155 Conn. 469","y":1967,"url":"https://www.courtlistener.com/c/Conn./155/469/","by":{"0":"32"}},{"t":"case","label":"Kissinger v. Reporters Committee for Freedom of the Press","cite":"445 U.S. 136","y":1980,"id":"1979/78-1088","sc":1,"sum":"Henry Kissinger served as an Assistant to the President for National Security Affairs from 1969 to 1975 and as Secretary of State from 1973 to 1977. Throughout these periods, his secretaries monitored his telephone conversations and recorded their contents either by shorthand or on tape. The stenographic notes or tapes were used to prepare summaries and sometimes verbatim transcripts of the conversations (hereafter …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Long v. Insurance Company of North America","cite":"670 F.2d 930","y":1982,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/670/930/","by":{"0":"43"}},{"t":"case","label":"Middlesex County Sewerage Authority v. National Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"op":2,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Northwest Airlines, Inc. v. Transport Workers Union of America","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"op":4,"sum":"Petitioner has neither a federal statutory nor a federal common-law right to contribution from respondent unions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 25, 26, 36","1":"21","2":"36","3":"11"}},{"t":"case","label":"Oxford University Bank v. Lansuppe Feeder, LLC","cite":"933 F.3d 99","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/933/99/","op":4,"sum":"Recognizing that §47(b)(2) “identifies a ‘class of persons’ who benefit from the availability of the right of action,” namely, “parties to a contract whose provisions violate the ICA” (citation and emphasis omitted).","sumSrc":"brief:2","by":{"0":"8, 13, 14, 42","1":"4, 9, 11, 24-26, 28, 29, 31","2":"14, 15, 23, 24, 27, 34","3":"21"}},{"t":"case","label":"Saba Capital CEF Opportunities 1, Ltd. v. Nuveen Floating Rate Income Fund","cite":"88 F.4th 103","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/88/103/","op":1,"by":{"0":"9, 11, 12","2":"16, 19"}},{"t":"case","label":"Securities & Exchange Commission v. Capital Gains Research Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"op":1,"by":{"0":"4","2":"4"}},{"t":"case","label":"Simmons v. Himmelreich","cite":"578 U.S. 621","y":2016,"id":"2015/15-109","sc":1,"sum":"The Court determined that the judgment bar of the Federal Tort Claims Act (FTCA) does not apply to claims dismissed for falling under the exceptions to the FTCA.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Simonson v. Fendell","cite":"675 P.2d 1218","y":1984,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/675/1218/","by":{"0":"43"}},{"t":"case","label":"Stoneridge Investment Partners, LLC v. Scientific-Atlanta, Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"ar":1,"sum":"The Court held that, under Central Bank and Section 10(b), securities fraud plaintiffs cannot sue \"aiders and abettors\" like Scientific-Atlanta. The Court noted Congress' subsequent failure to create a right of private action against aiders and abettors in the Private Securities Litigation Reform Act for support of its position that no such right should be allowed in the present case.","sumSrc":"Oyez","by":{"0":"29","1":"13","3":"6"}},{"t":"case","label":"Superintendent of Insurance v. Bankers Life & Casualty Co.","cite":"404 U.S. 6","y":1971,"id":"1971/70-60","sc":1,"sum":"Section 10 (b) of the Securities Exchange Act of 1934 makes it unlawful to use \"in connection with the purchase or sale\" of any security \"any manipulative or deceptive device or contrivance\" in contravention of the Securities and Exchange Commission's rules and regulations. Section 10 (b) prohibits the use of any deceptive device in the \"sale\" of any security by \"any person,\" and it is irrelevant that Manhattan was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Thompson v. Thompson","cite":"484 U.S. 174","y":1988,"id":"1987/86-964","sc":1,"op":3,"sum":"The PKPA does not provide an implied cause of action in federal court to determine which of two conflicting state custody decisions is valid. The context in which the PKPA was enacted-the existence of jurisdictional deadlocks among the States in custody cases and a nationwide problem of interstate parental kidnaping-suggests that Congress' principal aim was to extend the requirements of the Full Faith and Credit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 21, 22, 23, 26","1":"3, 11, 17, 18, 20","3":"4"}},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"op":6,"ar":1,"sum":"There is no implied private cause of action for damages under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 21, 23","1":"4, 11, 21-23","2":"23, 36, 42","3":"7, 11"}},{"t":"case","label":"Transamerica Mortgage Advisors, Inc. v. Lewis (TAMA)","cite":"444 U.S. 11","y":1979,"id":"1978/77-1645","sc":1,"op":16,"sum":"Reasoning that because one provision of the 618 FS CREDIT OPPORTUNITIES CORP. v. SABA CAPITAL MASTER FUND, LTD. ICA authorizes private lawsuits for damages, we should not imply a private right of action for that relief elsewhere.","sumSrc":"opinion","by":{"0":"44, 45, 46, 47, 48, 49","1":"4, 6, 22, 24, 26-28, 30","2":"1, 2, 3, 7, 8, 9, 23, 28, 32, 36, 37, 40, 41, 42, 43, 44, 45, 46, 48","3":"15, 17, 18, 19"}},{"t":"case","label":"United States v. National Ass’n of Securities Dealers","cite":"422 U.S. 694","y":1975,"id":"1974/73-1701","sc":1,"sum":"Section 22 (d) of the Investment Company Act of 1940 provides that \"no dealer shall sell [mutual-fund shares] to any person except a dealer, a principal underwriter, or the issuer, except at a current public offering price described in the prospectus.\" Section 22 (f) authorizes mutual funds to impose restrictions on the negotiability and transferability of shares, provided they conform with the fund's registration …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4","1":"5, 23"}},{"t":"case","label":"United States v. Oakland Cannabis Buyers’ Cooperative","cite":"532 U.S. 483","y":2001,"id":"2000/00-151","sc":1,"op":10,"sum":"The Court held that there is no medical necessity exception to the Controlled Substances Act's prohibitions on manufacturing and distributing marijuana. \"The statute reflects a determination that marijuana has no medical benefits worthy of an exception, \" wrote Justice Thomas, therefore, \"medical necessity is not a defense to manufacturing and distributing marijuana.\" Justice John Paul Stevens' concurring opinion, which was joined by Justices David H. Souter and Ruth Bader Ginsburg, argued that \"[b]ecause necessity was raised in this case as a defense to distribution, the Court need not venture an opinion on whether the defense is available to anyone other than distributors.\" Justice Stephen G. Breyer took no part in the consideration or decision of the case.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Universities Research Ass’n v. Coutu","cite":"450 U.S. 754","y":1981,"id":"1980/78-1945","sc":1,"op":1,"sum":"The Davis-Bacon Act does not confer upon an employee a private right of action for back wages under a contract that has been administratively determined not to call for work subject to the Act and thus does not contain prevailing wage stipulations. Pp. 767-784. UNIVERSITIES RESEARCH ASSN. v. COUTU (a) While requiring that certain stipulations be placed in federal construction contracts for the benefit of mechanics …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 38","1":"21"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"20, 26, 27","1":"2, 12, 13","2":"23, 32"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"0":"20"}},{"t":"usc","label":"5 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/5/7101","stext":{"head":"§7101. Findings and purpose","paras":[[0,"(a) The Congress finds that—"],[1,"(1) experience in both private and public employment indicates that the statutory protection of the right of employees to organize, bargain collectively, and participate through labor organizations of their own choosing in decisions which affect them—"],[2,"(A) safeguards the public interest,"],[2,"(B) contributes to the effective conduct of public business, and"],[2,"(C) facilitates and encourages the amicable settlements of disputes between employees and their employers involving conditions of employment; and"],[1,"(2) the public interest demands the highest standards of employee performance and the continued development and implementation of modern and progressive work practices to facilitate and improve employee performance and the efficient accomplishment of the operations of the Government."],[0,"Therefore, labor organizations and collective bargaining in the civil service are in the public interest."],[0,"(b) It is the purpose of this chapter to prescribe certain rights and obligations of the employees of the Federal Government and to establish procedures which are designed to meet the special requirements and needs of the Government. The provisions of this chapter should be interpreted in a manner consistent with the requirement of an effective and efficient Government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7101?type=usc&year=mostrecent&link-type=html"},"head":"§7101. Findings and purpose","tname":"Government Organization and Employees","by":{"0":"24","3":"17"}},{"t":"usc","label":"15 U.S.C. § 77","url":"https://www.law.cornell.edu/uscode/text/15/77","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 77aaa","url":"https://www.law.cornell.edu/uscode/text/15/77aaa","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","stext":{"head":"§78a. Short title","paras":[[0,"This chapter may be cited as the \"Securities Exchange Act of 1934.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78a?type=usc&year=mostrecent&link-type=html"},"head":"§78a. Short title","tname":"Commerce and Trade","by":{"0":"4, 33","1":"2"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"by":{"0":"28, 29"}},{"t":"usc","label":"15 U.S.C. § 78n","url":"https://www.law.cornell.edu/uscode/text/15/78n","subs":["(a)"],"by":{"0":"26"}},{"t":"usc","label":"15 U.S.C. § 78p","url":"https://www.law.cornell.edu/uscode/text/15/78p","subs":["(b)"],"stext":{"head":"§78p. Directors, officers, and principal stockholders","paras":[[0,"(a) Disclosures required"],[0,"(1) Directors, officers, and principal stockholders required to file"],[1,"Every person who is directly or indirectly the beneficial owner of more than 10 percent of any class of any equity security (other than an exempted security) which is registered pursuant to section 78l of this title, or who is a director or an officer of the issuer of such security, shall file the statements required by this subsection with the Commission."],[0,"(2) Time of filing"],[1,"The statements required by this subsection shall be filed—"],[2,"(A) at the time of the registration of such security on a national securities exchange or by the effective date of a registration statement filed pursuant to section 78l(g) of this title;"],[2,"(B) within 10 days after he or she becomes such beneficial owner, director, or officer, or within such shorter time as the Commission may establish by rule;"],[2,"(C) if there has been a change in such ownership, or if such person shall have purchased or sold a security-based swap agreement involving such equity security, before the end of the second business day following the day on which the subject transaction has been executed, or at such other time as the Commission shall establish, by rule, in any case in which the Commission determines that such 2-day period is not feasible."],[0,"(3) Contents of statements"],[1,"A statement filed—"],[2,"(A) under subparagraph (A) or (B) of paragraph (2) shall contain a statement of the amount of all equity securities of such issuer of which the filing person is the beneficial owner; and"],[2,"(B) under subparagraph (C) of such paragraph shall indicate ownership by the filing person at the date of filing, any such changes in such ownership, and such purchases and sales of the security-based swap agreements or security-based swaps as have occurred since the most recent such filing under such subparagraph."],[0,"(4) Electronic filing and availability"],[1,"Beginning not later than 1 year after July 30, 2002—"],[2,"(A) a statement filed under subparagraph (C) of paragraph (2) shall be filed electronically;"],[2,"(B) the Commission shall provide each such statement on a publicly accessible Internet site not later than the end of the business day following that filing; and"],[2,"(C) the issuer (if the issuer maintains a corporate website) shall provide that statement on that corporate website, not later than the end of the business day following that filing."],[0,"(b) Profits from purchase and sale of security within six months"],[0,"For the purpose of preventing the unfair use of information which may have been obtained by such beneficial owner, director, or officer by reason of his relationship to the issuer, any profit realized by him from any purchase and sale, or any sale and purchase, of any equity security of such issuer (other than an exempted security) or a security-based swap agreement involving any such equity security within any period of less than six months, unless such security or security-based swap agreement was acquired in good faith in connection with a debt previously contracted, shall inure to and be recoverable by the issuer, irrespective of any intention on the part of such beneficial owner, director, or officer in entering into such transaction of holding the security or security-based swap agreement purchased or of not repurchasing the security or security-based swap agreement sold for a period exceeding six months. Suit to recover such profit may be instituted at law or in equity in any court of competent jurisdiction by the issuer, or by the owner of any security of the issuer in the name and in behalf of the issuer if the issuer shall fail or refuse to bring such suit within sixty days after request or shall fail diligently to prosecute the same thereafter; but no such suit shall be brought more than two years after the date such profit was realized. This subsection shall not be construed to cover any transaction where such beneficial owner was not such both at the time of the purchase and sale, or the sale and purchase, of the security or security-based swap agreement or a security-based swap involved, or any transaction or transactions which the Commission by rules and regulations may exempt as not comprehended within the purpose of this subsection."],[0,"(c) Conditions for sale of security by beneficial owner, director, or officer"],[0,"It shall be unlawful for any such beneficial owner, director, or officer, directly or indirectly, to sell any equity security of such issuer (other than an exempted security), if the person selling the security or his principal (1) does not own the security sold, or (2) if owning the security, does not deliver it against such sale within twenty days thereafter, or does not within five days after such sale deposit it in the mails or other usual channels of transportation; but no person shall be deemed to have violated this subsection if he proves that notwithstanding the exercise of good faith he was unable to make such delivery or deposit within such time, or that to do so would cause undue inconvenience or expense."],[0,"(d) Securities held in investment account, transactions in ordinary course of business, and establishment of primary or secondary market"],[0,"The provisions of subsection (b) of this section shall not apply to any purchase and sale, or sale and purchase, and the provisions of subsection (c) of this section shall not apply to any sale, of an equity security not then or theretofore held by him in an investment account, by a dealer in the ordinary course of his business and incident to the establishment or maintenance by him of a primary or secondary market (otherwise than on a national securities exchange or an exchange exempted from registration under section 78e of this title) for such security. The Commission may, by such rules and regulations as it deems necessary or appropriate in the public interest, define and prescribe terms and conditions with respect to securities held in an investment account and transactions made in the ordinary course of business and incident to the establishment or maintenance of a primary or secondary market."],[0,"(e) Application of section to foreign or domestic arbitrage transactions"],[0,"The provisions of this section shall not apply to foreign or domestic arbitrage transactions unless made in contravention of such rules and regulations as the Commission may adopt in order to carry out the purposes of this section."],[0,"(f) Treatment of transactions in security futures products"],[0,"The provisions of this section shall apply to ownership of and transactions in security futures products."],[0,"(g) Limitation on Commission authority"],[0,"The authority of the Commission under this section with respect to security-based swap agreements shall be subject to the restrictions and limitations of section 78c–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78p?type=usc&year=mostrecent&link-type=html"},"head":"§78p. Directors, officers, and principal stockholders","tname":"Commerce and Trade","by":{"0":"16, 17, 37, 6, 37","1":"2, 6"}},{"t":"usc","label":"15 U.S.C. § 78q","url":"https://www.law.cornell.edu/uscode/text/15/78q","subs":["(a)"],"by":{"0":"33, 33"}},{"t":"usc","label":"15 U.S.C. § 78aa","url":"https://www.law.cornell.edu/uscode/text/15/78aa","by":{"0":"33, 34"}},{"t":"usc","label":"15 U.S.C. § 79","url":"https://www.law.cornell.edu/uscode/text/15/79","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 80a-1","url":"https://www.law.cornell.edu/uscode/text/15/80a-1","subs":["(b)(4)","(b)(8)","(b)","(b)(2)"],"stext":{"head":"§80a–1. Findings and declaration of policy","paras":[[0,"(a) Findings"],[0,"Upon the basis of facts disclosed by the record and reports of the Securities and Exchange Commission made pursuant to section 79z–4 1 of this title, and facts otherwise disclosed and ascertained, it is found that investment companies are affected with a national public interest in that, among other things—"],[1,"(1) the securities issued by such companies, which constitute a substantial part of all securities publicly offered, are distributed, purchased, paid for, exchanged, transferred, redeemed, and repurchased by use of the mails and means and instrumentalities of interstate commerce, and in the case of the numerous companies which issue redeemable securities this process of distribution and redemption is continuous;"],[1,"(2) the principal activities of such companies—investing, reinvesting, and trading in securities—are conducted by use of the mails and means and instrumentalities of interstate commerce, including the facilities of national securities exchanges, and constitute a substantial part of all transactions effected in the securities markets of the Nation;"],[1,"(3) such companies customarily invest and trade in securities issued by, and may dominate and control or otherwise affect the policies and management of, companies engaged in business in interstate commerce;"],[1,"(4) such companies are media for the investment in the national economy of a substantial part of the national savings and may have a vital effect upon the flow of such savings into the capital markets; and"],[1,"(5) the activities of such companies, extending over many States, their use of the instrumentalities of interstate commerce and the wide geographic distribution of their security holders, make difficult, if not impossible, effective State regulation of such companies in the interest of investors."],[0,"(b) Policy"],[0,"Upon the basis of facts disclosed by the record and reports of the Securities and Exchange Commission made pursuant to section 79z–4 1 of this title, and facts otherwise disclosed and ascertained, it is declared that the national public interest and the interest of investors are adversely affected—"],[1,"(1) when investors purchase, pay for, exchange, receive dividends upon, vote, refrain from voting, sell, or surrender securities issued by investment companies without adequate, accurate, and explicit information, fairly presented, concerning the character of such securities and the circumstances, policies, and financial responsibility of such companies and their management;"],[1,"(2) when investment companies are organized, operated, managed, or their portfolio securities are selected, in the interest of directors, officers, investment advisers, depositors, or other affiliated persons thereof, in the interest of underwriters, brokers, or dealers, in the interest of special classes of their security holders, or in the interest of other investment companies or persons engaged in other lines of business, rather than in the interest of all classes of such companies' security holders;"],[1,"(3) when investment companies issue securities containing inequitable or discriminatory provisions, or fail to protect the preferences and privileges of the holders of their outstanding securities;"],[1,"(4) when the control of investment companies is unduly concentrated through pyramiding or inequitable methods of control, or is inequitably distributed, or when investment companies are managed by irresponsible persons;"],[1,"(5) when investment companies, in keeping their accounts, in maintaining reserves, and in computing their earnings and the asset value of their outstanding securities, employ unsound or misleading methods, or are not subjected to adequate independent scrutiny;"],[1,"(6) when investment companies are reorganized, become inactive, or change the character of their business, or when the control or management thereof is transferred, without the consent of their security holders;"],[1,"(7) when investment companies by excessive borrowing and the issuance of excessive amounts of senior securities increase unduly the speculative character of their junior securities; or"],[1,"(8) when investment companies operate without adequate assets or reserves."],[0,"It is declared that the policy and purposes of this subchapter, in accordance with which the provisions of this subchapter shall be interpreted, are to mitigate and, so far as is feasible, to eliminate the conditions enumerated in this section which adversely affect the national public interest and the interest of investors."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80a-1?type=usc&year=mostrecent&link-type=html"},"head":"§80a–1. Findings and declaration of policy","tname":"Commerce and Trade","by":{"0":"40, 41, 43, 44, 45, 46, 48, 5, 5","1":"1","2":"5, 6, 30","3":"19, 20, 21, 22, 23, 24, 16, 16"}},{"t":"usc","label":"15 U.S.C. § 80a-6","url":"https://www.law.cornell.edu/uscode/text/15/80a-6","subs":["(c)"],"stext":{"head":"§80a–6. Exemptions","paras":[[0,"(a) Exemption of specified investment companies"],[0,"The following investment companies are exempt from the provisions of this subchapter:"],[1,"(1) Any company which since the effective date of this subchapter or within five years prior to such date has been reorganized under the supervision of a court of competent jurisdiction, if (A) such company was not an investment company at the commencement of such reorganization proceedings, (B) at the conclusion of such proceedings all outstanding securities of such company were owned by creditors of such company or by persons to whom such securities were issued on account of creditors' claims, and (C) more than 50 per centum of the voting securities of such company, and securities representing more than 50 per centum of the net asset value of such company, are currently owned beneficially by not more than twenty-five persons; but such exemption shall terminate if any security of which such company is the issuer is offered for sale or sold to the public after the conclusion of such proceedings by the issuer or by or through any underwriter. For the purposes of this paragraph, any new company organized as part of the reorganization shall be deemed the same company as its predecessor; and beneficial ownership shall be determined in the manner provided in section 80a–3(c)(1) of this title."],[1,"(2) Any issuer as to which there is outstanding a writing filed with the Commission by the Federal Savings and Loan Insurance Corporation stating that exemption of such issuer from the provisions of this subchapter is consistent with the public interest and the protection of investors and is necessary or appropriate by reason of the fact that such issuer holds or proposes to acquire any assets or any product of any assets which have been segregated (A) from assets of any company which at the filing of such writing is an insured institution within the meaning of section 1724(a) 1 of title 12, or (B) as a part of or in connection with any plan for or condition to the insurance of accounts of any company by said corporation or the conversion of any company into a Federal savings and loan association. Any such writing shall expire when canceled by a writing similarly filed or at the expiration of two years after the date of its filing, whichever first occurs; but said corporation may, nevertheless, before, at, or after the expiration of any such writing file another writing or writings with respect to such issuer."],[1,"(3) Any company which prior to March 15, 1940, was and now is a wholly-owned subsidiary of a registered face-amount certificate company and was prior to said date and now is organized and operating under the insurance laws of any State and subject to supervision and examination by the insurance commissioner thereof, and which prior to March 15, 1940, was and now is engaged, subject to such laws, in business substantially all of which consists of issuing and selling only to residents of such State and investing the proceeds from, securities providing for or representing participations or interests in intangible assets consisting of mortgages or other liens on real estate or notes or bonds secured thereby or in a fund or deposit of mortgages or other liens on real estate or notes or bonds secured thereby or having outstanding such securities so issued and sold."],[1,"(4)(A) Any company that is not engaged in the business of issuing redeemable securities, the operations of which are subject to regulation by the State in which the company is organized under a statute governing entities that provide financial or managerial assistance to enterprises doing business, or proposing to do business, in that State if—"],[2,"(i) the organizational documents of the company state that the activities of the company are limited to the promotion of economic, business, or industrial development in the State through the provision of financial or managerial assistance to enterprises doing business, or proposing to do business, in that State, and such other activities that are incidental or necessary to carry out that purpose;"],[2,"(ii) immediately following each sale of the securities of the company by the company or any underwriter for the company, not less than 80 percent of the securities of the company being offered in such sale, on a class-by-class basis, are held by persons who reside or who have a substantial business presence in that State;"],[2,"(iii) the securities of the company are sold, or proposed to be sold, by the company or by any underwriter for the company, solely to accredited investors, as that term is defined in section 77b(a)(15) of this title, or to such other persons that the Commission, as necessary or appropriate in the public interest and consistent with the protection of investors, may permit by rule, regulation, or order; and"],[2,"(iv) the company does not purchase any security issued by an investment company or by any company that would be an investment company except for the exclusions from the definition of the term \"investment company\" under paragraph (1) or (7) of section 80a–3(c) of this title, other than—"],[3,"(I) any debt security that meets such standards of credit-worthiness as the Commission shall adopt; or"],[3,"(II) any security issued by a registered open-end investment company that is required by its investment policies to invest not less than 65 percent of its total assets in securities described in subclause (I) or securities that are determined by such registered open-end investment company to be comparable in quality to securities described in subclause (I)."],[1,"(B) Notwithstanding the exemption provided by this paragraph, section 80a–9 of this title (and, to the extent necessary to enforce section 80a–9 of this title, sections 80a–37 through 80a–50 of this title) shall apply to a company described in this paragraph as if the company were an investment company registered under this subchapter."],[1,"(C) Any company proposing to rely on the exemption provided by this paragraph shall file with the Commission a notification stating that the company intends to do so, in such form and manner as the Commission may prescribe by rule."],[1,"(D) Any company meeting the requirements of this paragraph may rely on the exemption provided by this paragraph upon filing with the Commission the notification required by subparagraph (C), until such time as the Commission determines by order that such reliance is not in the public interest or is not consistent with the protection of investors."],[1,"(E) The exemption provided by this paragraph may be subject to such additional terms and conditions as the Commission may by rule, regulation, or order determine are necessary or appropriate in the public interest or for the protection of investors."],[0,"(b) Exemption of employees' security company upon application; matters considered"],[0,"Upon application by any employees' security company, the Commission shall by order exempt such company from the provisions of this subchapter and of the rules and regulations hereunder, if and to the extent that such exemption is consistent with the protection of investors. In determining the provisions to which such an order of exemption shall apply, the Commission shall give due weight, among other things, to the form of organization and the capital structure of such company, the persons by whom its voting securities, evidences of indebtedness, and other securities are owned and controlled, the prices at which securities issued by such company are sold and the sales load thereon, the disposition of the proceeds of such sales, the character of the securities in which such proceeds are invested, and any relationship between such company and the issuer of any such security."],[0,"(c) Exemption of persons, securities or any class or classes of persons as necessary and appropriate in public interest"],[0,"The Commission, by rules and regulations upon its own motion, or by order upon application, may conditionally or unconditionally exempt any person, security, or transaction, or any class or classes of persons, securities, or transactions, from any provision or provisions of this subchapter or of any rule or regulation thereunder, if and to the extent that such exemption is necessary or appropriate in the public interest and consistent with the protection of investors and the purposes fairly intended by the policy and provisions of this subchapter."],[0,"(d) Exemption of closed-end investment companies"],[0,"The Commission, by rules and regulations or order, shall exempt a closed-end investment company from any or all provisions of this subchapter, but subject to such terms and conditions as may be necessary or appropriate in the public interest or for the protection of investors, if—"],[1,"(1) the aggregate sums received by such company from the sale of all its outstanding securities, plus the aggregate offering price of all securities of which such company is the issuer and which it proposes to offer for sale, do not exceed $10,000,000, or such other amount as the Commission may set by rule, regulation, or order;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80a-6?type=usc&year=mostrecent&link-type=html"},"head":"§80a–6. Exemptions","tname":"Commerce and Trade","by":{"0":"4, 6, 6, 17, 38, 39, 41","1":"6","2":"45"}},{"t":"usc","label":"15 U.S.C. § 80a-8","url":"https://www.law.cornell.edu/uscode/text/15/80a-8","subs":["(a)","(b)"],"stext":{"head":"§80a–8. Registration of investment companies","paras":[[0,"(a) Notification of registration; effective date of registration"],[0,"Any investment company organized or otherwise created under the laws of the United States or of a State may register for the purposes of this subchapter by filing with the Commission a notification of registration, in such form as the Commission shall by rules and regulations prescribe as necessary or appropriate in the public interest or for the protection of investors. An investment company shall be deemed to be registered upon receipt by the Commission of such notification of registration."],[0,"(b) Registration statement; contents"],[0,"Every registered investment company shall file with the Commission, within such reasonable time after registration as the Commission shall fix by rules and regulations, an original and such copies of a registration statement, in such form and containing such of the following information and documents as the Commission shall by rules and regulations prescribe as necessary or appropriate in the public interest or for the protection of investors:"],[1,"(1) a recital of the policy of the registrant in respect of each of the following types of activities, such recital consisting in each case of a statement whether the registrant reserves freedom of action to engage in activities of such type, and if such freedom of action is reserved, a statement briefly indicating, insofar as is practicable, the extent to which the registrant intends to engage therein: (A) the classification and subclassifications, as defined in sections 80a–4 and 80a–5 of this title, within which the registrant proposes to operate; (B) borrowing money; (C) the issuance of senior securities; (D) engaging in the business of underwriting securities issued by other persons; (E) concentrating investments in a particular industry or group of industries; (F) the purchase and sale of real estate and commodities, or either of them; (G) making loans to other persons; and (H) portfolio turn-over (including a statement showing the aggregate dollar amount of purchases and sales of portfolio securities, other than Government securities, in each of the last three full fiscal years preceding the filing of such registration statement);"],[1,"(2) a recital of all investment policies of the registrant, not enumerated in paragraph (1), which are changeable only if authorized by shareholder vote;"],[1,"(3) a recital of all policies of the registrant, not enumerated in paragraphs (1) and (2), in respect of matters which the registrant deems matters of fundamental policy;"],[1,"(4) the name and address of each affiliated person of the registrant; the name and principal address of every company, other than the registrant, of which each such person is an officer, director, or partner; a brief statement of the business experience for the preceding five years of each officer and director of the registrant; and"],[1,"(5) the information and documents which would be required to be filed in order to register under the Securities Act of 1933 [15 U.S.C. 77a et seq.] and the Securities Exchange Act of 1934 [15 U.S.C. 78a et seq.], all securities (other than short-term paper) which the registrant has outstanding or proposes to issue."],[0,"(c) Alternative information"],[0,"The Commission shall make provision, by permissive rules and regulations or order, for the filing of the following, or so much of the following as the Commission may designate, in lieu of the information and documents required pursuant to subsection (b):"],[1,"(1) copies of the most recent registration statement filed by the registrant under the Securities Act of 1933 [15 U.S.C. 77a et seq.] and currently effective under such Act, or if the registrant has not filed such a statement, copies of a registration statement filed by the registrant under the Securities Exchange Act of 1934 [15 U.S.C. 78a et seq.] and currently effective under such Act;"],[1,"(2) copies of any reports filed by the registrant pursuant to section 78m or 78o(d) of this title; and"],[1,"(3) a report containing reasonably current information regarding the matters included in copies filed pursuant to paragraphs (1) and (2) of this subsection, and such further information regarding matters not included in such copies as the Commission is authorized to require under subsection (b)."],[0,"(d) Registration of unit investment trusts"],[0,"If the registrant is a unit investment trust substantially all of the assets of which are securities issued by another registered investment company, the Commission is authorized to prescribe for the registrant, by rules and regulations or order, a registration statement which eliminates inappropriate duplication of information contained in the registration statement filed under this section by such other investment company."],[0,"(e) Failure to file registration statement or omissions of material fact"],[0,"If it appears to the Commission that a registered investment company has failed to file the registration statement required by this section or a report required pursuant to section 80a–29 (a) or (b) of this title, or has filed such a registration statement or report but omitted therefrom material facts required to be stated therein, or has filed such a registration statement or report in violation of section 80a–33(b) of this title, the Commission shall notify such company by registered mail or by certified mail of the failure to file such registration statement or report, or of the respects in which such registration statement or report appears to be materially incomplete or misleading, as the case may be, and shall fix a date (in no event earlier than thirty days after the mailing of such notice) prior to which such company may file such registration statement or report or correct the same. If such registration statement or report is not filed or corrected within the time so fixed by the Commission or any extension thereof, the Commission, after appropriate notice and opportunity for hearing, and upon such conditions and with such exemptions as it deems appropriate for the protection of investors, may by order suspend the registration of such company until such statement or report is filed or corrected, or may by order revoke such registration, if the evidence establishes—"],[1,"(1) that such company has failed to file a registration statement required by this section or a report required pursuant to section 80a–29(a) or (b) of this title, or has filed such a registration statement or report but omitted therefrom material facts required to be stated therein, or has filed such a registration statement or report in violation of section 80a–33(b) of this title; and"],[1,"(2) that such suspension or revocation is in the public interest."],[0,"(f) Cessation of existence as investment company"],[0,"Whenever the Commission, on its own motion or upon application, finds that a registered investment company has ceased to be an investment company, it shall so declare by order and upon the taking effect of such order the registration of such company shall cease to be in effect. If necessary for the protection of investors, an order under this subsection may be made upon appropriate conditions. The Commission's denial of any application under this subsection shall be by order."],[0,"(g) Data standards for registration statements"],[0,"(1) Requirement"],[1,"The Commission shall, by rule, adopt data standards for all registration statements required to be filed with the Commission under this section, except that the Commission may exempt exhibits, signatures, and certifications from those data standards."],[0,"(2) Consistency"],[1,"The data standards required under paragraph (1) shall incorporate, and ensure compatibility with (to the extent feasible), all applicable data standards established in the rules promulgated under section 5334 of title 12, including, to the extent practicable, by having the characteristics described in clauses (i) through (vi) of subsection (c)(1)(B) of such section 5334."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80a-8?type=usc&year=mostrecent&link-type=html"},"head":"§80a–8. Registration of investment companies","tname":"Commerce and Trade","by":{"0":"32, 35, 32","1":"5"}},{"t":"usc","label":"15 U.S.C. § 80a-10","url":"https://www.law.cornell.edu/uscode/text/15/80a-10","subs":["(a)","(e)(3)"],"by":{"0":"5, 35"}},{"t":"usc","label":"15 U.S.C. § 80a-15","url":"https://www.law.cornell.edu/uscode/text/15/80a-15","subs":["(c)"],"by":{"0":"39"}},{"t":"usc","label":"15 U.S.C. § 80a-17","url":"https://www.law.cornell.edu/uscode/text/15/80a-17","subs":["(a)"],"by":{"0":"32, 32"}},{"t":"usc","label":"15 U.S.C. § 80a-18","url":"https://www.law.cornell.edu/uscode/text/15/80a-18","subs":["(i)"],"stext":{"head":"§80a–18. Capital structure of investment companies","paras":[[0,"(a) Qualifications on issuance of senior securities"],[0,"It shall be unlawful for any registered closed-end company to issue any class of senior security, or to sell any such security of which it is the issuer, unless—"],[1,"(1) if such class of senior security represents an indebtedness—"],[2,"(A) immediately after such issuance or sale, it will have an asset coverage of at least 300 per centum;"],[2,"(B) provision is made to prohibit the declaration of any dividend (except a dividend payable in stock of the issuer), or the declaration of any other distribution, upon any class of the capital stock of such investment company, or the purchase of any such capital stock, unless, in every such case, such class of senior securities has at the time of the declaration of any such dividend or distribution or at the time of any such purchase an asset coverage of at least 300 per centum after deducting the amount of such dividend, distribution, or purchase price, as the case may be, except that dividends may be declared upon any preferred stock if such senior security representing indebtedness has an asset coverage of at least 200 per centum at the time of declaration thereof after deducting the amount of such dividend; and"],[2,"(C) provision is made either—"],[3,"(i) that, if on the last business day of each of twelve consecutive calendar months such class of senior securities shall have an asset coverage of less than 100 per centum, the holders of such securities voting as a class shall be entitled to elect at least a majority of the members of the board of directors of such registered company, such voting right to continue until such class of senior security shall have an asset coverage of 110 per centum or more on the last business day of each of three consecutive calendar months, or"],[3,"(ii) that, if on the last business day of each of twenty-four consecutive calendar months such class of senior securities shall have an asset coverage of less than 100 per centum, an event of default shall be deemed to have occurred;"],[1,"(2) if such class of senior security is a stock—"],[2,"(A) immediately after such issuance or sale it will have an asset coverage of at least 200 per centum;"],[2,"(B) provision is made to prohibit the declaration of any dividend (except a dividend payable in common stock of the issuer), or the declaration of any other distribution, upon the common stock of such investment company, or the purchase of any such common stock, unless in every such case such class of senior security has at the time of the declaration of any such dividend or distribution or at the time of any such purchase an asset coverage of at least 200 per centum after deducting the amount of such dividend, distribution or purchase price, as the case may be;"],[2,"(C) provision is made to entitle the holders of such senior securities, voting as a class, to elect at least two directors at all times, and, subject to the prior rights, if any, of the holders of any other class of senior securities outstanding, to elect a majority of the directors if at any time dividends on such class of securities shall be unpaid in an amount equal to two full years' dividends on such securities, and to continue to be so represented until all dividends in arrears shall have been paid or otherwise provided for;"],[2,"(D) provision is made requiring approval by the vote of a majority of such securities, voting as a class, of any plan of reorganization adversely affecting such securities or of any action requiring a vote of security holders as in section 80a–13(a) of this title provided; and"],[2,"(E) such class of stock shall have complete priority over any other class as to distribution of assets and payment of dividends, which dividends shall be cumulative."],[0,"(b) Asset coverage in respect of senior securities"],[0,"The asset coverage in respect of a senior security provided for in subsection (a) may be determined on the basis of values calculated as of a time within forty-eight hours (not including Sundays or holidays) next preceding the time of such determination. The time of issue or sale shall, in the case of an offering of such securities to existing stockholders of the issuer, be deemed to be the first date on which such offering is made, and in all other cases shall be deemed to be the time as of which a firm commitment to issue or sell and to take or purchase such securities shall be made."],[0,"(c) Prohibitions relating to issuance of senior securities"],[0,"Notwithstanding the provisions of subsection (a) it shall be unlawful for any registered closed-end investment company to issue or sell any senior security representing indebtedness if immediately thereafter such company will have outstanding more than one class of senior security representing indebtedness, or to issue or sell any senior security which is a stock if immediately thereafter such company will have outstanding more than one class of senior security which is a stock, except that (1) any such class of indebtedness or stock may be issued in one or more series: Provided, That no such series shall have a preference or priority over any other series upon the distribution of the assets of such registered closed-end company or in respect of the payment of interest or dividends, and (2) promissory notes or other evidences of indebtedness issued in consideration of any loan, extension, or renewal thereof, made by a bank or other person and privately arranged, and not intended to be publicly distributed, shall not be deemed to be a separate class of senior securities representing indebtedness within the meaning of this subsection."],[0,"(d) Warrants and rights to subscription"],[0,"It shall be unlawful for any registered management company to issue any warrant or right to subscribe to or purchase a security of which such company is the issuer, except in the form of warrants or rights to subscribe expiring not later than one hundred and twenty days after their issuance and issued exclusively and ratably to a class or classes of such company's security holders; except that any warrant may be issued in exchange for outstanding warrants in connection with a plan of reorganization."],[0,"(e) Application of section to specific senior securities"],[0,"The provisions of this section shall not apply to any senior securities issued or sold by any registered closed-end company—"],[1,"(1) for the purpose of refunding through payment, purchase, redemption, retirement, or exchange, any senior security of such registered investment company except that no senior security representing indebtedness shall be so issued or sold for the purpose of refunding any senior security which is a stock; or"],[1,"(2) pursuant to any plan of reorganization (other than for refunding as referred to in paragraph (1) of this subsection), provided—"],[2,"(A) that such senior securities are issued or sold for the purpose of substituting or exchanging such senior securities for outstanding senior securities, and if such senior securities represent indebtedness they are issued or sold for the purpose of substituting or exchanging such senior securities for outstanding senior securities representing indebtedness, of any registered investment company which is a party to such plan of reorganization; or"],[2,"(B) that the total amount of such senior securities so issued or sold pursuant to such plan does not exceed the total amount of senior securities of all the companies which are parties to such plan, and the total amount of senior securities representing indebtedness so issued or sold pursuant to such plan does not exceed the total amount of senior securities representing indebtedness of all such companies, or, alternatively, the total amount of such senior securities so issued or sold pursuant to such plan does not have the effect of increasing the ratio of senior securities representing indebtedness to the securities representing stock or the ratio of senior securities representing stock to securities junior thereto when compared with such ratios as they existed before such reorganization."],[0,"(f) Senior securities securing loans from bank; securities not included in \"senior security\""],[0,"(1) It shall be unlawful for any registered open-end company to issue any class of senior security or to sell any senior security of which it is the issuer, except that any such registered company shall be permitted to borrow from any bank: Provided, That immediately after any such borrowing there is an asset coverage of at least 300 per centum for all borrowings of such registered company: And provided further, That in the event that such asset coverage shall at any time fall below 300 per centum such registered company shall, within three days thereafter (not including Sundays and holidays) or such longer period as the Commission may prescribe by rules and regulations, reduce the amount of its borrowings to an extent that the asset coverage of such borrowings shall be at least 300 per centum."],[0,"(2) \"Senior security\" shall not, in the case of a registered open-end company, include a class or classes or a number of series of preferred or special stock each of which is preferred over all other classes or series in respect of assets specifically allocated to that class or series: Provided, That (A) such company has outstanding no class or series of stock which is not so preferred over all other classes or series, or (B) the only other outstanding class of the issuer's stock consists of a common stock upon which no dividend (other than a liquidating dividend) is permitted to be paid and which in the aggregate represents not more than one-half of 1 per centum of the issuer's outstanding voting securities. For the purpose of insuring fair and equitable treatment of the holders of the outstanding voting securities of each class or series of stock of such company, the Commission may by rule, regulation, or order direct that any matter required to be submitted to the holders of the outstanding voting securities of such company shall not be deemed to have been effectively acted upon unless approved by the holders of such percentage (not exceeding a majority) of the outstanding voting securities of each class or series of stock affected by such matter as shall be prescribed in such rule, regulation, or order."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80a-18?type=usc&year=mostrecent&link-type=html"},"head":"§80a–18. Capital structure of investment companies","tname":"Commerce and Trade","by":{"0":"39, 4, 12, 13, 14","1":"8, 9, 15, 22","2":"6, 19"}},{"t":"usc","label":"15 U.S.C. § 80a-29","url":"https://www.law.cornell.edu/uscode/text/15/80a-29","subs":["(h)"],"by":{"0":"4, 6, 16, 17, 36, 37, 48","1":"2, 4, 6, 21, 22"}},{"t":"usc","label":"15 U.S.C. § 80a-35","url":"https://www.law.cornell.edu/uscode/text/15/80a-35","subs":["(b)"],"by":{"0":"4, 6, 17, 25, 36, 37, 49","1":"2, 4, 6, 21, 22"}},{"t":"usc","label":"15 U.S.C. § 80a-41","url":"https://www.law.cornell.edu/uscode/text/15/80a-41","subs":["(a)","(b)","(d)","(e)","(e)(2)(A)"],"by":{"0":"4, 5, 6, 35, 35, 36, 36, 5, 6, 36, 5, 6, 36, 36","1":"6, 6, 6"}},{"t":"usc","label":"15 U.S.C. § 80a-46","url":"https://www.law.cornell.edu/uscode/text/15/80a-46","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(3)","(b)(1976)"],"stext":{"head":"§80a–46. Validity of contracts","paras":[[0,"(a) Waiver of compliance as void"],[0,"Any condition, stipulation, or provision binding any person to waive compliance with any provision of this subchapter or with any rule, regulation, or order thereunder shall be void."],[0,"(b) Equitable results; rescission; severance"],[0,"(1) A contract that is made, or whose performance involves, a violation of this subchapter, or of any rule, regulation, or order thereunder, is unenforceable by either party (or by a nonparty to the contract who acquired a right under the contract with knowledge of the facts by reason of which the making or performance violated or would violate any provision of this subchapter or of any rule, regulation, or order thereunder) unless a court finds that under the circumstances enforcement would produce a more equitable result than nonenforcement and would not be inconsistent with the purposes of this subchapter."],[0,"(2) To the extent that a contract described in paragraph (1) has been performed, a court may not deny rescission at the instance of any party unless such court finds that under the circumstances the denial of rescission would produce a more equitable result than its grant and would not be inconsistent with the purposes of this subchapter."],[0,"(3) This subsection shall not apply (A) to the lawful portion of a contract to the extent that it may be severed from the unlawful portion of the contract, or (B) to preclude recovery against any person for unjust enrichment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80a-46?type=usc&year=mostrecent&link-type=html"},"head":"§80a–46. Validity of contracts","tname":"Commerce and Trade","by":{"0":"33, 39, 41, 42, 6, 7, 30, 43, 44, 45, 46, 47, 48, 49, 2, 7, 30, 34, 42, 43, 31, 32, 34, 42, 43, 44, 31","1":"30-32, 27, 1, 3-5, 7-12, 15-31, 3, 7, 11, 15, 16, 18, 19, 21, 23, 25, 3, 4, 7, 9, 11, 16, 18, 19, 21, 25, 7, 16","2":"28, 2, 20, 23, 39, 41, 42, 43","3":"17, 23, 24, 16, 17, 18, 20, 22, 24, 9, 19, 14, 15, 16, 18, 23, 23"}},{"t":"usc","label":"15 U.S.C. § 80b-1","url":"https://www.law.cornell.edu/uscode/text/15/80b-1","stext":{"head":"§80b–1. Findings","paras":[[0,"Upon the basis of facts disclosed by the record and report of the Securities and Exchange Commission made pursuant to section 79z–4 1 of this title, and facts otherwise disclosed and ascertained, it is found that investment advisers are of national concern, in that, among other things—"],[1,"(1) their advice, counsel, publications, writings, analyses, and reports are furnished and distributed, and their contracts, subscription agreements, and other arrangements with clients are negotiated and performed, by the use of the mails and means and instrumentalities of interstate commerce;"],[1,"(2) their advice, counsel, publications, writings, analyses, and reports customarily relate to the purchase and sale of securities traded on national securities exchanges and in interstate over-the-counter markets, securities issued by companies engaged in business in interstate commerce, and securities issued by national banks and member banks of the Federal Reserve System; and"],[1,"(3) the foregoing transactions occur in such volume as substantially to affect interstate commerce, national securities exchanges, and other securities markets, the national banking system and the national economy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-1?type=usc&year=mostrecent&link-type=html"},"head":"§80b–1. Findings","tname":"Commerce and Trade","by":{"0":"3, 4, 45, 46, 47, 48","1":"26","3":"15, 17, 18, 19"}},{"t":"usc","label":"15 U.S.C. § 80b-6","url":"https://www.law.cornell.edu/uscode/text/15/80b-6","stext":{"head":"§80b–6. Prohibited transactions by investment advisers","paras":[[0,"It shall be unlawful for any investment adviser by use of the mails or any means or instrumentality of interstate commerce, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud any client or prospective client;"],[1,"(2) to engage in any transaction, practice, or course of business which operates as a fraud or deceit upon any client or prospective client;"],[1,"(3) acting as principal for his own account, knowingly to sell any security to or purchase any security from a client, or acting as broker for a person other than such client, knowingly to effect any sale or purchase of any security for the account of such client, without disclosing to such client in writing before the completion of such transaction the capacity in which he is acting and obtaining the consent of the client to such transaction. The prohibitions of this paragraph shall not apply to any transaction with a customer of a broker or dealer if such broker or dealer is not acting as an investment adviser in relation to such transaction; or"],[1,"(4) to engage in any act, practice, or course of business which is fraudulent, deceptive, or manipulative. The Commission shall, for the purposes of this paragraph (4) by rules and regulations define, and prescribe means reasonably designed to prevent, such acts, practices, and courses of business as are fraudulent, deceptive, or manipulative."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-6?type=usc&year=mostrecent&link-type=html"},"head":"§80b–6. Prohibited transactions by investment advisers","tname":"Commerce and Trade","by":{"0":"46","1":"26"}},{"t":"usc","label":"15 U.S.C. § 80b-15","url":"https://www.law.cornell.edu/uscode/text/15/80b-15","subs":["(b)"],"stext":{"head":"§80b–15. Validity of contracts","paras":[[0,"(a) Waiver of compliance as void"],[0,"Any condition, stipulation, or provision binding any person to waive compliance with any provision of this subchapter or with any rule, regulation, or order thereunder shall be void."],[0,"(b) Rights affected by invalidity"],[0,"Every contract made in violation of any provision of this subchapter and every contract heretofore or hereafter made, the performance of which involves the violation of, or the continuance of any relationship or practice in violation of any provision of this subchapter, or any rule, regulation, or order thereunder, shall be void (1) as regards the rights of any person who, in violation of any such provision, rule, regulation, or order, shall have made or engaged in the performance of any such contract, and (2) as regards the rights of any person who, not being a party to such contract, shall have acquired any right thereunder with actual knowledge of the facts by reason of which the making or performance of such contract was in violation of any such provision."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-15?type=usc&year=mostrecent&link-type=html"},"head":"§80b–15. Validity of contracts","tname":"Commerce and Trade","by":{"0":"19, 46, 45, 46, 47, 48","1":"26-28","3":"2, 17, 18"}},{"t":"usc","label":"20 U.S.C. § 1232g","url":"https://www.law.cornell.edu/uscode/text/20/1232g","subs":["(b)(1)"],"by":{"0":"22, 24, 22"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","subs":["(a)"],"stext":{"head":"§1681. Sex","paras":[[0,"(a) Prohibition against discrimination; exceptions"],[0,"No person in the United States shall, on the basis of sex, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any education program or activity receiving Federal financial assistance, except that:"],[0,"(1) Classes of educational institutions subject to prohibition"],[1,"in regard to admissions to educational institutions, this section shall apply only to institutions of vocational education, professional education, and graduate higher education, and to public institutions of undergraduate higher education;"],[0,"(2) Educational institutions commencing planned change in admissions"],[1,"in regard to admissions to educational institutions, this section shall not apply (A) for one year from June 23, 1972, nor for six years after June 23, 1972, in the case of an educational institution which has begun the process of changing from being an institution which admits only students of one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education or (B) for seven years from the date an educational institution begins the process of changing from being an institution which admits only students of only one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education, whichever is the later;"],[0,"(3) Educational institutions of religious organizations with contrary religious tenets"],[1,"this section shall not apply to an educational institution which is controlled by a religious organization if the application of this subsection would not be consistent with the religious tenets of such organization;"],[0,"(4) Educational institutions training individuals for military services or merchant marine"],[1,"this section shall not apply to an educational institution whose primary purpose is the training of individuals for the military services of the United States, or the merchant marine;"],[0,"(5) Public educational institutions with traditional and continuing admissions policy"],[1,"in regard to admissions this section shall not apply to any public institution of undergraduate higher education which is an institution that traditionally and continually from its establishment has had a policy of admitting only students of one sex;"],[0,"(6) Social fraternities or sororities; voluntary youth service organizations"],[1,"this section shall not apply to membership practices—"],[2,"(A) of a social fraternity or social sorority which is exempt from taxation under section 501(a) of title 26, the active membership of which consists primarily of students in attendance at an institution of higher education, or"],[2,"(B) of the Young Men's Christian Association, Young Women's Christian Association, Girl Scouts, Boy Scouts, Camp Fire Girls, and voluntary youth service organizations which are so exempt, the membership of which has traditionally been limited to persons of one sex and principally to persons of less than nineteen years of age;"],[0,"(7) Boy or Girl conferences"],[1,"this section shall not apply to—"],[2,"(A) any program or activity of the American Legion undertaken in connection with the organization or operation of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[2,"(B) any program or activity of any secondary school or educational institution specifically for—"],[3,"(i) the promotion of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[3,"(ii) the selection of students to attend any such conference;"],[0,"(8) Father-son or mother-daughter activities at educational institutions"],[1,"this section shall not preclude father-son or mother-daughter activities at an educational institution, but if such activities are provided for students of one sex, opportunities for reasonably comparable activities shall be provided for students of the other sex; and"],[0,"(9) Institution of higher education scholarship awards in \"beauty\" pageants"],[1,"this section shall not apply with respect to any scholarship or other financial assistance awarded by an institution of higher education to any individual because such individual has received such award in any pageant in which the attainment of such award is based upon a combination of factors related to the personal appearance, poise, and talent of such individual and in which participation is limited to individuals of one sex only, so long as such pageant is in compliance with other nondiscrimination provisions of Federal law."],[0,"(b) Preferential or disparate treatment because of imbalance in participation or receipt of Federal benefits; statistical evidence of imbalance"],[0,"Nothing contained in subsection (a) of this section shall be interpreted to require any educational institution to grant preferential or disparate treatment to the members of one sex on account of an imbalance which may exist with respect to the total number or percentage of persons of that sex participating in or receiving the benefits of any federally supported program or activity, in comparison with the total number or percentage of persons of that sex in any community, State, section, or other area: Provided, That this subsection shall not be construed to prevent the consideration in any hearing or proceeding under this chapter of statistical evidence tending to show that such an imbalance exists with respect to the participation in, or receipt of the benefits of, any such program or activity by the members of one sex."],[0,"(c) \"Educational institution\" defined"],[0,"For purposes of this chapter an educational institution means any public or private preschool, elementary, or secondary school, or any institution of vocational, professional, or higher education, except that in the case of an educational institution composed of more than one school, college, or department which are administratively separate units, such term means each such school, college, or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1681?type=usc&year=mostrecent&link-type=html"},"head":"§1681. Sex","tname":"Education","by":{"0":"32, 33, 33","3":"7, 7"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","stext":{"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","paras":[[0,"No person in the United States shall, on the ground of race, color, or national origin, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any program or activity receiving Federal financial assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000d?type=usc&year=mostrecent&link-type=html"},"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","tname":"The Public Health and Welfare","by":{"0":"33","3":"17"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"0":"25"}},{"t":"law","label":"Pub. L. No. 96-477","url":"https://www.govinfo.gov/link/statute/94/2275","by":{"0":"47","1":"29","2":"11, 34","3":"2"}},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","by":{"0":"28"}},{"t":"reg","label":"17 C.F.R. pt. 270","url":"https://www.ecfr.gov/current/title-17/part-270","by":{"0":"35"}},{"t":"reg","label":"17 C.F.R. § 270.22c-1","url":"https://www.ecfr.gov/current/title-17/section-270.22c-1","subs":["(a)"],"by":{"0":"8"}},{"t":"case","label":"American Express Co. v. Italian Colors Rest.","cite":"570 U.S. 228","y":2013,"id":"2012/12-133","sc":1,"sum":"The Court held that a clause prohibiting class action suits was enforceable even though it would cause costly arbitration.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"ar":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"1":"20, 21","3":"5"}},{"t":"case","label":"Burks v. Lasker","cite":"441 U.S. 471","y":1979,"id":"1978/77-1724","sc":1,"sum":"In suits alleging violations of the ICA and IAA, federal courts should, as a matter of federal law, apply state law governing the authority of independent directors to discontinue derivative suits to the extent such law is consistent with the policies of the ICA and the IAA. Congress did not require that States, or federal courts, absolutely forbid director termination of all nonfrivolous actions.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 5, 17"}},{"t":"case","label":"City of Oklahoma City v. Tuttle","cite":"471 U.S. 808","y":1985,"id":"1984/83-1919","sc":1,"sum":"The Court held that the district court’s instructions to the jury improperly allowed a plaintiff to impose liability on the city without proof of a single action taken by a municipal policy maker.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Credit Suisse Sec. (USA) LLC v. Simmonds","cite":"566 U.S. 221","y":2012,"id":"2011/10-1261","sc":1,"sum":"The Court held that Section 16(b) of the 1934 Securities Exchange Act is subject to tolling, where tolling starts after the filing of a Section 16(a) claim.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"DeVillier v. Texas","cite":"601 U.S. 285","y":2024,"id":"2023/22-913","sc":1,"sum":"Owners of property north of U. S. Interstate Highway 10 adversely affected by the flood evacuation barrier constructed by Texas should be permitted on remand to pursue their Takings Clause claims through the cause of action available under Texas law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"op":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"13"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"op":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"28","3":"22"}},{"t":"case","label":"George v. Tate","cite":"102 U.S. 564","y":1881,"id":"scdb/1880-062","sc":1,"sum":"This was an action by Samuel W. Tate upon a bond bearing date Sept. 19, 1872, executed to John J. Myers andWilliam Gréen by the. firm of M. B. George & Brothers as principal, and J. W. L. Slavens as surety. The bond was subject to the condition, —","sumSrc":"Headnote (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Health & Hosp. Corp. v. Talevski","cite":"599 U.S. 166","y":2023,"id":"2022/21-806","sc":1,"sum":"The provisions of the Federal Nursing Home Reform Act at issue unambiguously create rights enforceable under 42 U. S. C. §1983, and private enforcement under §1983 is compatible with the FNHRA’s remedial scheme.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"10, 14-16","2":"26, 27","3":"14"}},{"t":"case","label":"Holder v. Martinez Gutierrez","cite":"566 U.S. 583","y":2012,"id":"2011/10-1542","sc":1,"sum":"The Court held that an unemancipated minor cannot use his or her parent's years of residency to fulfill the requirements for having a removal from the country stayed under 8 U.S. C. 1229(a).","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Irving v. Humphrey","cite":"1 Hopk. Ch. 284","y":1824,"court":"N.Y.","url":"https://www.courtlistener.com/c/Hopk.%20Ch./1/284/","by":{"1":"19"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Jones v. Harris Assocs. L.P.","cite":"559 U.S. 335","y":2010,"id":"2009/08-586","sc":1,"sum":"The Court held that Section 36(b) of the Investment Company Act requires a determination that the financial adviser charges a fee that is \"so disproportionately large is bears no reasonable relationship to the services rendered\" before legal action may be taken.","sumSrc":"Oyez","by":{"1":"5, 17","2":"4, 5"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs., Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"sum":"A court entertaining a derivative action under the ICA must apply the demand futility exception as it is defined by the law of the State of incorporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 17"}},{"t":"case","label":"Kelly v. Kosuga","cite":"358 U.S. 516","y":1959,"id":"1958/267","sc":1,"sum":"In this suit brought in a Federal District Court on grounds of diversity of citizenship by a seller to recover from a buyer the unpaid balance due in respect to a lawful sale for a fair consideration, the District Courtr properly granted the plaintiff's motion to strike an affirmative defense pleaded by the buyer to the effect that the sale was made pursuant to, and as an indivisible part of, an agreement which …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Medina v. Planned Parenthood S. Atl.","cite":"145 S. Ct. 2219","y":2025,"id":"2024/23-1275","sc":1,"sum":"Medicaid’s any-qualified-provider provision—42 U. S. C. §1396a(a)(23)(A)—does not clearly and unambiguously confer individual rights on Medicaid beneficiaries enforceable under 42 U. S. C. §1983.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"2, 3, 5, 10-16, 20, 21, 28","3":"4"}},{"t":"case","label":"Mills v. Electric Auto-Lite Co.","cite":"396 U.S. 375","y":1970,"id":"1969/64","sc":1,"op":2,"sum":"Petitioners, minority shareholders of respondent Electric Auto-Lite Co., brought this action derivatively and on behalf of minority shareholders as a class to set aside a merger of Auto-Lite and the Mergenthaler Linotype Co. (which before the merger owned over half of Auto-Lite's stock). Petitioners charged that the proxy solicitation for the merger by Auto-Lite's management was materially misleading and violated § …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26","2":"8"}},{"t":"case","label":"Minnesota v. Northern Sec. Co.","cite":"194 U.S. 48","y":1904,"id":"scdb/1903-078","sc":1,"sum":"Consent of parties can never confer jurisdiction upon a Federal court. If the record does not affirmatively show jurisdiction in the Circuit Court, this court must, upon its own motion, so declare, and make such order as will prevent the Circuit Court from exercising an authority.not conferred upon it by statute..","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Northstar Fin. Advisors, Inc. v. Schwab Invs.","cite":"615 F.3d 1106","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/615/1106/","by":{"1":"21"}},{"t":"case","label":"Olmsted v. Pruco Life Ins. Co.","cite":"283 F.3d 429","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/283/429/","ar":3,"by":{"1":"24"}},{"t":"case","label":"Riley v. Bondi","cite":"145 S. Ct. 2190","y":2025,"id":"2024/23-1270","sc":1,"sum":"Order from the Board of Immigration Appeals denying deferral of removal in “withholding only” proceeding is not a “final order of removal” under 8 U. S. C. §1252(b)(1); the 30-day filing deadline to challenge a final order of removal under §1252(b)(1) is a claims-processing rule, not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Santomenno ex rel. John Hancock Trust v. John Hancock Life Ins. Co.","cite":"677 F.3d 178","y":2012,"url":"https://www.courtlistener.com/c/F.3d/677/178/","op":1,"by":{"1":"15, 22, 24, 27, 28"}},{"t":"case","label":"Steinberg v. Janus Capital Mgmt., LLC","cite":"457 Fed. Appx. 261","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./457/261/","op":1,"by":{"1":"15"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"587 U.S. 554","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"UFCW Local 1500 Pension Fund v. Mayer","cite":"895 F.3d 695","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/895/695/","op":1,"by":{"1":"15, 21, 23, 24, 28","3":"20, 21"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"19"}},{"t":"usc","label":"15 U.S.C. § 80a-3","url":"https://www.law.cornell.edu/uscode/text/15/80a-3","subs":["(a)(1)"],"stext":{"head":"§80a–3. Definition of investment company","paras":[[0,"(a) Definitions"],[0,"(1) When used in this subchapter, \"investment company\" means any issuer which—"],[1,"(A) is or holds itself out as being engaged primarily, or proposes to engage primarily, in the business of investing, reinvesting, or trading in securities;"],[1,"(B) is engaged or proposes to engage in the business of issuing face-amount certificates of the installment type, or has been engaged in such business and has any such certificate outstanding; or"],[1,"(C) is engaged or proposes to engage in the business of investing, reinvesting, owning, holding, or trading in securities, and owns or proposes to acquire investment securities having a value exceeding 40 per centum of the value of such issuer's total assets (exclusive of Government securities and cash items) on an unconsolidated basis."],[0,"(2) As used in this section, \"investment securities\" includes all securities except (A) Government securities, (B) securities issued by employees' securities companies, and (C) securities issued by majority-owned subsidiaries of the owner which (i) are not investment companies, and (ii) are not relying on the exception from the definition of investment company in paragraph (1) or (7) of subsection (c)."],[0,"(b) Exemption from provisions"],[0,"Notwithstanding paragraph (1)(C) of subsection (a), none of the following persons is an investment company within the meaning of this subchapter:"],[1,"(1) Any issuer primarily engaged, directly or through a wholly-owned subsidiary or subsidiaries, in a business or businesses other than that of investing, reinvesting, owning, holding, or trading in securities."],[1,"(2) Any issuer which the Commission, upon application by such issuer, finds and by order declares to be primarily engaged in a business or businesses other than that of investing, reinvesting, owning, holding, or trading in securities either directly or (A) through majority-owned subsidiaries or (B) through controlled companies conducting similar types of businesses. The filing of an application under this paragraph in good faith by an issuer other than a registered investment company shall exempt the applicant for a period of sixty days from all provisions of this subchapter applicable to investment companies as such. For cause shown, the Commission by order may extend such period of exemption for an additional period or periods. Whenever the Commission, upon its own motion or upon application, finds that the circumstances which gave rise to the issuance of an order granting an application under this paragraph no longer exist, the Commission shall by order revoke such order."],[1,"(3) Any issuer all the outstanding securities of which (other than short-term paper and directors' qualifying shares) are directly or indirectly owned by a company excepted from the definition of investment company by paragraph (1) or (2) of this subsection."],[0,"(c) Further exemptions"],[0,"Notwithstanding subsection (a), none of the following persons is an investment company within the meaning of this subchapter:"],[1,"(1) Any issuer whose outstanding securities (other than short-term paper) are beneficially owned by not more than one hundred persons (or, in the case of a qualifying venture capital fund, 250 persons) and which is not making and does not presently propose to make a public offering of its securities. Such issuer shall be deemed to be an investment company for purposes of the limitations set forth in subparagraphs (A)(i) and (B)(i) of section 80a–12(d)(1) of this title governing the purchase or other acquisition by such issuer of any security issued by any registered investment company and the sale of any security issued by any registered open-end investment company to any such issuer. For purposes of this paragraph:"],[2,"(A) Beneficial ownership by a company shall be deemed to be beneficial ownership by one person, except that, if the company owns 10 per centum or more of the outstanding voting securities of the issuer, and is or, but for the exception provided for in this paragraph or paragraph (7), would be an investment company, the beneficial ownership shall be deemed to be that of the holders of such company's outstanding securities (other than short-term paper)."],[2,"(B) Beneficial ownership by any person who acquires securities or interests in securities of an issuer described in the first sentence of this paragraph shall be deemed to be beneficial ownership by the person from whom such transfer was made, pursuant to such rules and regulations as the Commission shall prescribe as necessary or appropriate in the public interest and consistent with the protection of investors and the purposes fairly intended by the policy and provisions of this subchapter, where the transfer was caused by legal separation, divorce, death, or other involuntary event."],[2,"(C)(i) The term \"qualifying venture capital fund\" means a venture capital fund that has not more than $10,000,000 in aggregate capital contributions and uncalled committed capital, with such dollar amount to be indexed for inflation once every 5 years by the Commission, beginning from a measurement made by the Commission on a date selected by the Commission, rounded to the nearest $1,000,000."],[2,"(ii) The term \"venture capital fund\" has the meaning given the term in section 275.203(l)–1 of title 17, Code of Federal Regulations, or any successor regulation."],[1,"(2)(A) Any person primarily engaged in the business of underwriting and distributing securities issued by other persons, selling securities to customers, acting as broker, and acting as market intermediary, or any one or more of such activities, whose gross income normally is derived principally from such business and related activities."],[1,"(B) For purposes of this paragraph—"],[2,"(i) the term \"market intermediary\" means any person that regularly holds itself out as being willing contemporaneously to engage in, and that is regularly engaged in, the business of entering into transactions on both sides of the market for a financial contract or one or more such financial contracts; and"],[2,"(ii) the term \"financial contract\" means any arrangement that—"],[3,"(I) takes the form of an individually negotiated contract, agreement, or option to buy, sell, lend, swap, or repurchase, or other similar individually negotiated transaction commonly entered into by participants in the financial markets;"],[3,"(II) is in respect of securities, commodities, currencies, interest or other rates, other measures of value, or any other financial or economic interest similar in purpose or function to any of the foregoing; and"],[3,"(III) is entered into in response to a request from a counter party for a quotation, or is otherwise entered into and structured to accommodate the objectives of the counter party to such arrangement."],[1,"(3) Any bank or insurance company; any savings and loan association, building and loan association, cooperative bank, homestead association, or similar institution, or any receiver, conservator, liquidator, liquidating agent, or similar official or person thereof or therefor; or any common trust fund or similar fund maintained by a bank exclusively for the collective investment and reinvestment of moneys contributed thereto by the bank in its capacity as a trustee, executor, administrator, or guardian, if—"],[2,"(A) such fund is employed by the bank solely as an aid to the administration of trusts, estates, or other accounts created and maintained for a fiduciary purpose;"],[2,"(B) except in connection with the ordinary advertising of the bank's fiduciary services, interests in such fund are not—"],[3,"(i) advertised; or"],[3,"(ii) offered for sale to the general public; and"],[2,"(C) fees and expenses charged by such fund are not in contravention of fiduciary principles established under applicable Federal or State law."],[1,"(4) Any person substantially all of whose business is confined to making small loans, industrial banking, or similar businesses."],[1,"(5) Any person who is not engaged in the business of issuing redeemable securities, face-amount certificates of the installment type or periodic payment plan certificates, and who is primarily engaged in one or more of the following businesses: (A) Purchasing or otherwise acquiring notes, drafts, acceptances, open accounts receivable, and other obligations representing part or all of the sales price of merchandise, insurance, and services; (B) making loans to manufacturers, wholesalers, and retailers of, and to prospective purchasers of, specified merchandise, insurance, and services; and (C) purchasing or otherwise acquiring mortgages and other liens on and interests in real estate."],[1,"(6) Any company primarily engaged, directly or through majority-owned subsidiaries, in one or more of the businesses described in paragraphs (3), (4), and (5) of this subsection, or in one or more of such businesses (from which not less than 25 per centum of such company's gross income during its last fiscal year was derived) together with an additional business or businesses other than investing, reinvesting, owning, holding, or trading in securities."],[1,"(7)(A) Any issuer, the outstanding securities of which are owned exclusively by persons who, at the time of acquisition of such securities, are qualified purchasers, and which is not making and does not at that time propose to make a public offering of such securities. Securities that are owned by persons who received the securities from a qualified purchaser as a gift or bequest, or in a case in which the transfer was caused by legal separation, divorce, death, or other involuntary event, shall be deemed to be owned by a qualified purchaser, subject to such rules, regulations, and orders as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80a-3?type=usc&year=mostrecent&link-type=html"},"head":"§80a–3. Definition of investment company","tname":"Commerce and Trade","by":{"1":"5","2":"4"}},{"t":"usc","label":"15 U.S.C. § 80a-4","url":"https://www.law.cornell.edu/uscode/text/15/80a-4","subs":["(3)"],"by":{"1":"8"}},{"t":"usc","label":"15 U.S.C. § 80a-7","url":"https://www.law.cornell.edu/uscode/text/15/80a-7","by":{"1":"5"}},{"t":"usc","label":"15 U.S.C. § 80a-37","url":"https://www.law.cornell.edu/uscode/text/15/80a-37","subs":["(a)"],"by":{"1":"6"}},{"t":"usc","label":"15 U.S.C. § 80a-42","url":"https://www.law.cornell.edu/uscode/text/15/80a-42","by":{"1":"6"}},{"t":"law","label":"Pub. L. No. 91-547","url":"https://www.govinfo.gov/link/statute/84/1428","by":{"1":"6"}},{"t":"usc","label":"15 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/15/1","stext":{"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","paras":[[0,"Every contract, combination in the form of trust or otherwise, or conspiracy, in restraint of trade or commerce among the several States, or with foreign nations, is declared to be illegal. Every person who shall make any contract or engage in any combination or conspiracy hereby declared to be illegal shall be deemed guilty of a felony, and, on conviction thereof, shall be punished by fine not exceeding $100,000,000 if a corporation, or, if any other person, $1,000,000, or by imprisonment not exceeding 10 years, or by both said punishments, in the discretion of the court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","tname":"Commerce and Trade","by":{"1":"19"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"14"}},{"t":"case","label":"BNSF Ry. Co. v. Loos","cite":"586 U.S. 310","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"31"}},{"t":"case","label":"City of New Orleans v. La. Constr. Co.","cite":"129 U.S. 45","y":1889,"id":"scdb/1888-082","sc":1,"sum":"An intervention by third opposition, under §§ 395 to 400 of the Code of Practice of Louisiana, by a person claiming tliiat property seized on execution is exempt from seizure and sale, is a proceeding at law, and as such, is reviewable upon writ of error.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"25","3":"13"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"584 U.S. 79","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Lampf, Pleva, Lipkind, Prupis & Petigrow v. Gilbertson","cite":"501 U.S. 350","y":1991,"id":"1990/90-333","sc":1,"sum":"The judgment is reversed. 895 F. 2d 1416, 1417, and 1418, reversed. JUSTICE BLACKMUN delivered the opinion of the Court with respect to Parts I, II-B, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Lantau Holdings Ltd. v. Gen. Pac. Grp. Ltd.","cite":"81 N.Y.S.3d 384","y":2018,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.3d/81/384/","by":{"2":"44"}},{"t":"case","label":"Meriwether v. Garrett","cite":"102 U.S. 472","y":1880,"id":"scdb/1880-049","sc":1,"sum":"On Feb. 28,. 1879, Robert Garrett and others filed their bill in' the court below against the City of Memphis, Tennessee, setting for.th that they are the owners and holders of overdue and unpaid bonds and coupons and other evidences of her indebtedness to the amount of more tha,n $100,000, upon much of which indebtedness'they have secured judgments and writs of mandamus to compel-the collection thereof, but that, …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"25","3":"13"}},{"t":"case","label":"Merritt v. Craig","cite":"746 A.2d 923","y":2000,"court":"Md. Ct. Spec. App.","url":"https://www.courtlistener.com/c/A.2d/746/923/","by":{"2":"44"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Musick, Peeler & Garrett v. Emps. Ins. of Wausau","cite":"508 U.S. 286","y":1993,"id":"1992/92-34","sc":1,"sum":"Defendants in a 10b-5 action have a right to seek contribution as a matter of federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"sum":"The Court held that the punitive damages received by the O'Gilvies were not received \"on account of\" personal injuries,\" and therefore the provision did not apply and the damages were taxable.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Sackett v. EPA","cite":"566 U.S. 120","y":2012,"id":"2011/10-1062","sc":1,"sum":"The Court found that homeowners have a right to go to court over a Clean Water Act order of the Environmental Protection Agency.","sumSrc":"Oyez","by":{"2":"26","3":"13"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"2":"24, 34"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"op":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"United Sav. Ass’n of Tex. v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"SEC.Br., Olmstead v. Pruco Life Ins. Co. of N.J.","cite":"2001 WL 34113763","y":2002,"court":"2d Cir.","by":{"2":"13, 14, 24, 34"}},{"t":"case","label":"SEC.Br., Transamerica Mortg. Advisors, Inc. v. Lewis","cite":"1979 WL 213662","y":1979,"court":"U.S. Feb. 9","by":{"2":"8, 14"}},{"t":"case","label":"Aetna Health Inc. v. Davila","cite":"542 U.S. 200","y":2004,"id":"2003/02-1845","sc":1,"sum":"The Court held that Congress intended ERISA to provide a uniform system for regulating retirement schemes and benefits. If a state law conflicts with ERISA, therefore, ERISA must be used in its place.","sumSrc":"Oyez","by":{"3":"22, 23"}},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Allen v. State Board of Elections","cite":"393 U.S. 544","y":1969,"id":"1968/3","sc":1,"sum":"The Supreme Court held that § 5 authorized a private right of action based on the remedial aims of the Voting Rights Act. The Court also interpreted the Act to provide that litigants bring these suits in their local district courts, and that three-judge district courts be convened (as was true at that time in constitutional challenges).","sumSrc":"Oyez","by":{"3":"5, 7, 14"}},{"t":"case","label":"Bufkin v. Collins","cite":"604 U.S. 369","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/369/","sc":1,"by":{"3":"19"}},{"t":"case","label":"Clark v. McDaniel","cite":"546 N.W.2d 590","y":1996,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/546/590/","by":{"3":"8"}},{"t":"case","label":"Corby v. Matthews","cite":"541 S.W.2d 789","y":1976,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W.2d/541/789/","by":{"3":"10"}},{"t":"case","label":"Crosby v. National Foreign Trade Council","cite":"530 U.S. 363","y":2000,"id":"1999/99-474","sc":1,"sum":"The Court held that \"the state Act is preempted, and its application unconstitutional, under the Supremacy Clause.\" Justice Souter wrote for the Court that Massachusetts' law created an obstacle to the President's discretion to control economic sanctions against Burma, interfered with Congress's intention to limit economic pressure against the Burmese Government, and was at odds with the President's authority to speak for the United States among the world's nations to develop a comprehensive, multilateral Burma strategy.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Fort Stewart Schools v. Federal Labor Relations Authority","cite":"495 U.S. 641","y":1990,"id":"1989/89-65","sc":1,"sum":"The Authority did not err in ruling that petitioner was required to bargain over the Union's proposals.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"14, 15"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Granite Buick GMC, Inc. v. Ray","cite":"856 N.W.2d 799","y":2014,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W.2d/856/799/","by":{"3":"8"}},{"t":"case","label":"Intel Corp. Investment Policy Committee v. Sulyma","cite":"589 U.S. 178","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Kaung v. Board of Managers of Biltmore Towers Condominium Ass’n","cite":"873 N.Y.S.2d 421","y":2008,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.2d/873/421/","by":{"3":"15"}},{"t":"case","label":"Kaung v. Board of Managers of Biltmore Towers Condominium Ass’n","cite":"895 N.Y.S.2d 505","y":2010,"court":"App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/895/505/","by":{"3":"15"}},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"sum":"The term “mistake” in Federal Rule of Civil Procedure 60(b)(1) includes a judge’s errors of law; because Kemp’s motion alleged such an error, it was cognizable under Rule 60(b)(1) and untimely under Rule 60(c)’s 1-year limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"12"}},{"t":"case","label":"Little Rock & Monroe Railway Co. v. Russell","cite":"113 S.W. 1021","y":1908,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W./113/1021/","by":{"3":"10"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"3":"14, 15"}},{"t":"case","label":"Morris v. Gresette","cite":"432 U.S. 491","y":1977,"id":"1976/75-1583","sc":1,"sum":"Section 5 of the Voting Rights Act of 1965 establishes two alternative methods by which States subject to the Act can obtain federal preclearance review of a change in their voting laws: (1) the State may file a declaratory judgment action in the District Court for the District of Columbia and subsequently may implement such change if that court declares that the change has no racially discriminatory purpose or …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Perkins v. Matthews","cite":"400 U.S. 379","y":1971,"id":"1970/46","sc":1,"sum":"Appellants, voters and candidates for city offices, sought to enjoin the 1969 election in Canton, Mississippi, alleging that the 1969 requirements differed from those in effect on November 1, 1964, and at the last city election in 1965, and that the city sought to enforce the changed requirements without following the approval procedure set forth in § 5 of the Voting Rights Act of 1965. Section 5 precludes a State …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Presley v. Etowah County Commission","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"sum":"In a majority opinion authored by Justice Anthony M. Kennedy, the Court determined that section 5 of the Voting Rights Act covers only changes that directly relate to voting.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Rudman v. Cowles Communications, Inc.","cite":"280 N.E.2d 867","y":1972,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/280/867/","by":{"3":"8"}},{"t":"case","label":"Schauer v. Mandarin Gems of California, Inc.","cite":"125 Cal. App. 4th 949","y":2005,"url":"https://www.courtlistener.com/c/Cal.%20App.%204th/125/949/","by":{"3":"15"}},{"t":"case","label":"United States v. Payner","cite":"447 U.S. 727","y":1980,"id":"1979/78-1729","sc":1,"sum":"At respondent's nonjury trial for falsifying a federal income tax return by denying that he maintained a foreign bank account, respondent moved to suppress a loan guarantee agreement in which he pledged the funds in the bank account as security. The District Court found respondent guilty on the basis of all the evidence, but then (1) found that the Government had discovered the guarantee agreement as the result of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Van Dyke Spinal Rehabilitation Center, PLLC v. USA Underwriters","cite":"2024 WL 2787560","y":2024,"court":"Mich. Ct. App. May 30","by":{"3":"8"}},{"t":"case","label":"W.R. Cobb Co. v. V.J. Designs, LLC","cite":"130 F.4th 224","y":2025,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/130/224/","by":{"3":"18, 19"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"3":"11"}},{"t":"usc","label":"2 U.S.C. § 190m","url":"https://www.law.cornell.edu/uscode/text/2/190m","by":{"3":"10"}},{"t":"usc","label":"47 U.S.C. § 409","url":"https://www.law.cornell.edu/uscode/text/47/409","subs":["(h)"],"by":{"3":"10"}},{"t":"usc","label":"52 U.S.C. § 10304","url":"https://www.law.cornell.edu/uscode/text/52/10304","subs":["(a)"],"by":{"3":"5, 7"}}]};